const all=$input.all();
const start=Math.floor(Date.now()/43200000)*43200000;
const seen=new Set();
const out=[];

for(const item of all){
  const p=item.json ?? {};
  if(!p.file_id) continue;
  const t=Date.parse(p.created_at ?? '');
  if(Number.isFinite(t) && t < start) continue;

  const key=p.file_unique_id || p.file_id;
  if(seen.has(key)) continue;
  seen.add(key);
  out.push({json:p});
}

if(!out.length){
  return [{json:{no_photos:true}}];
}

return out;

const items=$input.all();
const binary={};
let count=0;

for(const item of items){
  if(item.binary?.data){
    count++;
    binary[`image_${count}`]=item.binary.data;
  }
}

return [{json:{image_count:count},binary}];

const root=$json.output ?? $json;
const product=root.product ?? {};
const strategy=root.creative_strategy ?? {};
const raw=Array.isArray(strategy.scenes)?strategy.scenes:[];
if(raw.length!==4) throw new Error(`Expected 4 scenes, received ${raw.length}`);
const d=[3,3,3,4];

const scenes=raw.map((s,i)=>({
  scene_number:i+1,duration_seconds:d[i],
  visual_direction:s.visual_direction ?? "",
  visual_prompt:s.visual_prompt ?? "",
  on_screen_text:s.on_screen_text ?? "",
  voiceover_text:s.voiceover_text ?? "",
  transition:s.transition ?? ""
}));

return [{json:{
  action:root.action ?? "generate_video",
  telegram_message:root.telegram_message ?? "",
  affiliate_coupon:root.affiliate_coupon ?? "",
  product:{
    id:product.id ?? 0,name:product.name ?? "",brand:product.brand ?? "",
    category:product.category ?? "",url:product.url ?? "",image_url:product.image_url ?? "",
    rating:Number(product.rating ?? 0),reviews:product.reviews ?? "",
    bestseller_rank:product.bestseller_rank ?? "",
    identification_confidence:product.identification_confidence ?? "low"
  },
  verified_facts:Array.isArray(root.verified_facts)?root.verified_facts:[],
  creative_strategy:{
    hooks:Array.isArray(strategy.hooks)?strategy.hooks:[],
    best_hook:strategy.best_hook ?? "",
    voiceover:strategy.voiceover ?? "",
    tts_voiceover:strategy.tts_voiceover ?? strategy.voiceover ?? "",
    scenes,cta:strategy.cta ?? "",coupon_placement:strategy.coupon_placement ?? "",
    caption:strategy.caption ?? "",hashtags:Array.isArray(strategy.hashtags)?strategy.hashtags:[]
  },
  video_settings:{platform:"TikTok",duration_seconds:13,aspect_ratio:"9:16",width:1080,height:1920,fps:30,faceless:true,language:"Arabic"},
  total_scenes:4,total_duration_seconds:13,video_generation_ready:true,missing_requirements:[]
}}];

const data=$json;
const s=data.creative_strategy ?? {};
const scenes=Array.isArray(s.scenes)?s.scenes:[];
if(scenes.length!==4) throw new Error(`Expected 4 scenes, received ${scenes.length}`);
const d=[3,3,3,4];
return scenes.map((scene,i)=>({json:{
  scene_number:i+1,duration_seconds:d[i],
  visual_direction:scene.visual_direction ?? "",visual_prompt:scene.visual_prompt ?? "",
  on_screen_text:scene.on_screen_text ?? "",voiceover_text:scene.voiceover_text ?? "",
  transition:scene.transition ?? "",best_hook:s.best_hook ?? "",
  full_voiceover:s.voiceover ?? "",full_tts_voiceover:s.tts_voiceover ?? s.voiceover ?? "",
  cta:s.cta ?? "",coupon_placement:s.coupon_placement ?? "",caption:s.caption ?? "",
  hashtags:s.hashtags ?? [],hooks:s.hooks ?? [],
  affiliate_coupon:data.affiliate_coupon ?? "",product:data.product ?? {},
  video_settings:data.video_settings ?? {},total_scenes:4
}}));

const items=$input.all();
if(!items.length) throw new Error('No scenes received');
return items.map((item,index)=>{
  const binaries=item.binary ?? {};
  const keys=Object.keys(binaries);
  if(!keys.length) throw new Error(`No uploaded images found for scene ${index+1}`);
  const selected=index % keys.length;
  const key=keys[selected];
  return {
    json:{...item.json,assigned_image_key:key,assigned_image_number:selected+1,
          uploaded_images_count:keys.length,
          scene_file_name:`scene_${String(item.json.scene_number??index+1).padStart(2,'0')}.jpg`},
    binary:{source_image:binaries[key]}
  };
});

const items=$input.all();
const scenes=items
  .sort((a,b)=>Number(a.json.scene_number??0)-Number(b.json.scene_number??0))
  .map((item,i)=>({
    scene_number:i+1,duration_seconds:[3,3,3,4][i],
    fileUrl:item.json.fileUrl,downloadUrl:item.json.downloadUrl ?? "",
    on_screen_text:item.json.on_screen_text ?? "",transition:item.json.transition ?? ""
  }));
if(scenes.length!==4 || scenes.some(x=>!x.fileUrl)) throw new Error(`Need exactly 4 uploaded scene files. Received ${scenes.length}.`);
const first=items[0]?.json ?? {};
return [{json:{
  scenes,width:1080,height:1920,fps:30,
  affiliate_coupon:first.affiliate_coupon ?? "",
  full_voiceover:first.full_voiceover ?? "",
  full_tts_voiceover:first.full_tts_voiceover ?? first.full_voiceover ?? "",
  output_file_name:`tiktok_slideshow_${Date.now()}.mp4`
}}];

const data=$input.first().json;
const scenes=data.scenes ?? [];
if(scenes.length!==4) throw new Error('Expected 4 scenes');

let coupon=String(data.affiliate_coupon ?? '').trim();
if(!coupon){
  try{coupon=String($('Prepare Video Payload').first().json.affiliate_coupon ?? '').trim();}catch(e){}
}
if(!coupon) throw new Error('affiliate_coupon is empty.');

const AR={
'ء':['\uFE80',null,null,null],'آ':['\uFE81','\uFE82',null,null],'أ':['\uFE83','\uFE84',null,null],
'ؤ':['\uFE85','\uFE86',null,null],'إ':['\uFE87','\uFE88',null,null],'ئ':['\uFE89','\uFE8A','\uFE8B','\uFE8C'],
'ا':['\uFE8D','\uFE8E',null,null],'ب':['\uFE8F','\uFE90','\uFE91','\uFE92'],'ة':['\uFE93','\uFE94',null,null],
'ت':['\uFE95','\uFE96','\uFE97','\uFE98'],'ث':['\uFE99','\uFE9A','\uFE9B','\uFE9C'],
'ج':['\uFE9D','\uFE9E','\uFE9F','\uFEA0'],'ح':['\uFEA1','\uFEA2','\uFEA3','\uFEA4'],'خ':['\uFEA5','\uFEA6','\uFEA7','\uFEA8'],
'د':['\uFEA9','\uFEAA',null,null],'ذ':['\uFEAB','\uFEAC',null,null],'ر':['\uFEAD','\uFEAE',null,null],'ز':['\uFEAF','\uFEB0',null,null],
'س':['\uFEB1','\uFEB2','\uFEB3','\uFEB4'],'ش':['\uFEB5','\uFEB6','\uFEB7','\uFEB8'],'ص':['\uFEB9','\uFEBA','\uFEBB','\uFEBC'],
'ض':['\uFEBD','\uFEBE','\uFEBF','\uFEC0'],'ط':['\uFEC1','\uFEC2','\uFEC3','\uFEC4'],'ظ':['\uFEC5','\uFEC6','\uFEC7','\uFEC8'],
'ع':['\uFEC9','\uFECA','\uFECB','\uFECC'],'غ':['\uFECD','\uFECE','\uFECF','\uFED0'],
'ف':['\uFED1','\uFED2','\uFED3','\uFED4'],'ق':['\uFED5','\uFED6','\uFED7','\uFED8'],'ك':['\uFED9','\uFEDA','\uFEDB','\uFEDC'],
'ل':['\uFEDD','\uFEDE','\uFEDF','\uFEE0'],'م':['\uFEE1','\uFEE2','\uFEE3','\uFEE4'],'ن':['\uFEE5','\uFEE6','\uFEE7','\uFEE8'],
'ه':['\uFEE9','\uFEEA','\uFEEB','\uFEEC'],'و':['\uFEED','\uFEEE',null,null],'ى':['\uFEEF','\uFEF0',null,null],
'ي':['\uFEF1','\uFEF2','\uFEF3','\uFEF4']
};
const canPrev=c=>Boolean(AR[c]?.[1]);
const canNext=c=>Boolean(AR[c]?.[2]);

function shapeWord(word){
  const chars=Array.from(word);
  return chars.map((ch,i)=>{
    if(!AR[ch]) return ch;
    const p=chars[i-1],n=chars[i+1],f=AR[ch];
    const jp=p&&AR[p]&&canNext(p)&&canPrev(ch);
    const jn=n&&AR[n]&&canNext(ch)&&canPrev(n);
    if(jp&&jn&&f[3]) return f[3];
    if(jp&&f[1]) return f[1];
    if(jn&&f[2]) return f[2];
    return f[0];
  }).join('');
}
function prepareArabic(text=''){
  text=String(text);
  if(!/[\u0600-\u06FF]/.test(text)) return text;
  const tokens=text.split(/(\s+)/).map(t=>{
    if(/[\u0600-\u06FF]/.test(t)) return Array.from(shapeWord(t)).reverse().join('');
    return t;
  });
  return tokens.reverse().join('');
}
function esc(text=''){
  return String(text).replace(/⭐/g,'★').replace(/\\/g,'\\\\').replace(/'/g,"\\'")
    .replace(/:/g,'\\:').replace(/%/g,'\\%').replace(/\n/g,' ');
}
function reEsc(t=''){return String(t).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function fontSize(t=''){const l=String(t).length;return l<=20?58:l<=30?50:44;}

const filters=scenes.map((scene,i)=>{
  let original=String(scene.on_screen_text ?? '').trim();
  const last=i===scenes.length-1;
  original=original.replace(new RegExp(reEsc(coupon),'ig'),'').replace(/\s+/g,' ').trim();
  const txt=esc(prepareArabic(original));
  let f=`[${i}:v]scale=1080:1920:force_original_aspect_ratio=decrease,pad=1080:1920:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30,format=yuv420p,setpts=PTS-STARTPTS`;
  if(txt){
    f+=`,drawtext=font='DejaVu Sans':text='${txt}':fontsize=${fontSize(original)}:fontcolor=white:borderw=4:bordercolor=black:box=1:boxcolor=black@0.45:boxborderw=18:x=(w-text_w)/2:y=${last?'h*0.70':'h*0.78'}`;
  }
  if(last){
    f+=`,drawtext=font='DejaVu Sans':text='${esc(coupon)}':fontsize=96:fontcolor=#FFB000:borderw=6:bordercolor=black:box=1:boxcolor=black@0.58:boxborderw=24:x=(w-text_w)/2:y=h*0.81`;
  }
  return f+`[v${i}]`;
});
const concat=scenes.map((_,i)=>`[v${i}]`).join('')+`concat=n=${scenes.length}:v=1:a=0[v]`;
return [{json:{...data,affiliate_coupon:coupon,filter_graph_with_text:[...filters,concat].join(';')}}];

const data=$input.first().json;
let text=String(data.full_tts_voiceover ?? '').trim();
if(!text){try{text=String($('Prepare Video Payload').first().json.creative_strategy?.tts_voiceover ?? '').trim();}catch(e){}}
if(!text){try{text=String($('Prepare Video Payload').first().json.creative_strategy?.voiceover ?? '').trim();}catch(e){}}
if(!text) throw new Error('TTS voiceover text is empty.');
return [{json:{...data,voiceover_text:text,target_video_duration:13}}];

return [
 {json:{attempt:1,search_query:'site:noon.com/saudi-en/ "Best Price KSA" mascara Maybelline Essence LOREAL'}},
