 {json:{attempt:4,search_query:'site:noon.com/saudi-en/ "Best Price KSA" perfume fragrance beauty'}},
 {json:{attempt:5,search_query:'site:noon.com/saudi-en/ "Best Price KSA" makeup cosmetics blush lipstick concealer'}},
 {json:{attempt:6,search_query:'site:noon.com/saudi-en/ "Best Price KSA" haircare body care beauty bestseller'}}
];

