const data=$input.first().json;
const msg=data.choices?.[0]?.message ?? {};
const ann=Array.isArray(msg.annotations)?msg.annotations:[];
const num=v=>Number(String(v??'').replace(/,/g,'').trim())||0;
const clean=v=>String(v??'').replace(/\s*\|\s*Best Price KSA.*$/i,'').replace(/\s+/g,' ').trim();

const products=ann.filter(a=>a?.type==='url_citation').map(a=>{
 const c=a.url_citation ?? {};
 const url=String(c.url??'').trim(), name=clean(c.title), snippet=String(c.content??'').trim();
 const m=url.match(/\/([A-Z0-9]+)\/p\/?(?:[?#].*)?$/i);
 const code=m?.[1]?.toUpperCase() ?? '';
 const exact=url.startsWith('https://www.noon.com/saudi-en/') && !!code;
 const unavailable=/sorry!?\s*this product is not available|available soon|out of stock|sold out|currently unavailable|coming back soon/i.test(snippet);
 const evidence=/add(?:ed)? to cart|get it by|get it tomorrow|delivery information|free delivery|noon-express|order in\s*\d|only\s+\d+\s+left in stock/i.test(snippet);
 const available=exact && !unavailable && evidence;

 let rating=0,reviews=0;
 const rm=snippet.match(/\b([1-5](?:\.\d)?)\s*(?:starFilledV2|starFilled|stars?|★|⭐)/i);
 if(rm) rating=num(rm[1]);
 const rv=snippet.match(/\b([\d,]+)\s*(?:ratings?|reviews?)\b/i);
 if(rv) reviews=num(rv[1]);

 const sm=snippet.match(/\b([\d,]+)\+\s*(?:sold|bought)\s+recently\b/i);
 const sold=sm?num(sm[1]):0;
 const bestseller=/\bbest\s*seller\b|\bbestseller\b/i.test(snippet);
 const rank=snippet.match(/#\s*(\d+)\s+in\s+/i)||snippet.match(/(?:best\s*seller|bestseller)\s*#?\s*(\d+)/i);

 let q=0;
 if(rating>=4.7)q+=5;else if(rating>=4.5)q+=4;else if(rating>=4.2)q+=3;
 if(reviews>=1000)q+=5;else if(reviews>=500)q+=4;else if(reviews>=100)q+=3;else if(reviews>0)q+=1;
 if(sold>=1000)q+=6;else if(sold>=500)q+=5;else if(sold>=100)q+=4;else if(sold>0)q+=2;
 if(bestseller)q+=4;if(available)q+=2;

 const popularity=reviews>0||sold>0||bestseller;
 const pass=exact&&available&&rating>=4.2&&(reviews>=100||sold>=100||bestseller);

 return {search_valid:exact,name,url,source_product_code:code,search_snippet:snippet,exact_match:exact,
   available_now:available,rating,review_count:reviews,bestseller,bestseller_rank:rank?.[1]??'',
   sold_signal:sm?sm[0]:'',sold_recent_count:sold,popularity_verified:popularity,
   quality_score:q,pass_quality:pass,recommended:false,source:'Noon Saudi',target_country:'Saudi Arabia',
   verified_url:exact,availability_status:available?'verified_available':(unavailable?'verified_unavailable':'not_verified')};
}).filter(p=>p.search_valid);

if(!products.length) return [{json:{search_valid:false,reason:'No Saudi Noon product result found'}}];
return products.map(p=>({json:p}));

const raw=$input.all().map(i=>i.json).filter(Boolean);
const n=v=>Number(v??0)||0,s=v=>String(v??'').trim();

let p=raw.filter(x=>x.search_valid===true&&x.name&&x.url);
const seen=new Map();
for(const x of p){const k=s(x.source_product_code||x.url).toUpperCase();if(k&&!seen.has(k))seen.set(k,x);}
p=[...seen.values()];

p=p.filter(x=>{
 const url=s(x.url);
 if(!url.startsWith('https://www.noon.com/saudi-en/'))return false;
 if(!/\/[A-Z0-9]+\/p\/?(?:[?#].*)?$/i.test(url))return false;
 const t=`${s(x.name)} ${s(x.search_snippet)} ${url}`.toLowerCase();
 const beauty=/beauty|cosmetic|cosmetics|skincare|skin care|serum|moisturizer|moisturiser|sunscreen|sun care|\bspf\b|makeup|mascara|lipstick|concealer|foundation|blush|eyeliner|hair care|haircare|body care|body lotion|perfume|fragrance|eau de parfum|eau de toilette|\bedp\b|\bedt\b/.test(t);
 const blocked=/health & nutrition|health care|healing ointment|medicine|medical|pharmacy|pain relief|analgesic|antibiotic|antiseptic|wound|supplement|home & kitchen|home decor|home fragrance|room fragrance|air freshener|reed diffuser|scented candle|\bcandle\b/.test(t);
 return beauty&&!blocked;
});

p=p.map(x=>{
 let score=n(x.quality_score);
 if(x.available_now===true)score+=3;
 if(x.pass_quality===true)score+=4;
 if(x.bestseller===true)score+=2;
 score+=Math.min(n(x.review_count)/250,4)+Math.min(n(x.sold_recent_count)/250,4);
 return {...x,ranking_score:score};
});

p.sort((a,b)=>n(b.ranking_score)-n(a.ranking_score)||n(b.sold_recent_count)-n(a.sold_recent_count)||n(b.review_count)-n(a.review_count)||n(b.rating)-n(a.rating));
const strong=p.filter(x=>x.available_now===true&&(x.pass_quality===true||n(x.quality_score)>=6));
const src=strong.length?strong:p;
const top=src.slice(0,3).map((x,i)=>({...x,id:i+1,recommended:strong.length>0&&i===0}));

return [{json:{products:top,total_products:top.length,recommended_product_id:strong.length&&top.length?1:null,
 search_success:top.length>0,quality_mode:strong.length?'strong_verified_signals':'valid_products_limited_signals',
 debug:{received:raw.length,valid_beauty_saudi_products:p.length,strong_products:strong.length,returned_top_products:top.length}}}];

const input=$input.first().json;
const products=Array.isArray(input.products)?input.products:[];
const clean=v=>String(v??'').replace(/\s*\|\s*Best Price KSA.*$/i,'').replace(/\s+/g,' ').trim();
function cat(name='',url='',snippet=''){
 const t=`${name} ${url} ${snippet}`.toLowerCase();
 if(t.includes('mascara'))return'Makeup - Mascara';
 if(/lipstick|lip tint|lip gloss/.test(t))return'Makeup - Lips';
 if(/concealer|foundation|blush/.test(t))return'Makeup - Face';
 if(/eyeliner|eye shadow|eyeshadow/.test(t))return'Makeup - Eyes';
 if(/sunscreen|sun screen|sun care|\bspf\b/.test(t))return'Skincare - Sunscreen';
 if(/face cream|capsule cream|moisturizer|moisturiser/.test(t))return'Skincare - Moisturizer';
 if(/serum|niacinamide|hyaluronic/.test(t))return'Skincare - Serum';
 if(/hair care|haircare|shampoo|conditioner|hair mask|hair oil/.test(t))return'Hair Care';
 if(/body lotion|body butter|body oil|body care/.test(t))return'Body Care';
 if(/perfume|parfum|fragrance|eau de parfum|eau de toilette|\bedp\b|\bedt\b/.test(t))return'Fragrance';
 return'Beauty & Cosmetics';
}
const normalized=products.map((x,i)=>({...x,id:i+1,name:clean(x.name),category:x.category||cat(x.name,x.url,x.search_snippet),
 source:'Noon Saudi',target_country:'Saudi Arabia',verified_url:String(x.url??'').startsWith('https://www.noon.com/saudi-en/')}));
return [{json:{...input,products:normalized,total_products:normalized.length,source:'Noon Saudi',target_country:'Saudi Arabia'}}];

const input=$input.first().json;
const p=Array.isArray(input.products)?input.products.slice(0,3):[];
if(!p.length)return[{json:{products:[],total_products:0,recommended_product_id:null,telegram_message:'ملقتش دلوقتي منتجات Beauty مناسبة من نون السعودية. جرّب البحث مرة تانية.',search_success:false,source:'Noon Saudi',target_country:'Saudi Arabia'}}];

const lines=p.map((x,i)=>{
 const d=[];
 if(Number(x.rating??0)>0)d.push(`⭐ ${Number(x.rating).toFixed(1)}`);
 if(Number(x.review_count??0)>0)d.push(`${Number(x.review_count)} تقييم`);
 if(Number(x.sold_recent_count??0)>0)d.push(`${Number(x.sold_recent_count)}+ مبيع مؤخرًا`);
 if(x.bestseller===true)d.push(x.bestseller_rank?`🔥 Bestseller #${x.bestseller_rank}`:'🔥 Bestseller');
 if(x.available_now===true)d.push('✅ التوفر متحقق');
 return [`${i+1}️⃣ ${x.name}`,x.category?`التصنيف: ${x.category}`:'',d.length?d.join(' • '):'',`🔗 ${x.url}`].filter(Boolean).join('\n');
});
const strong=input.quality_mode==='strong_verified_signals';
return[{json:{
 products:p.map((x,i)=>({...x,id:i+1,recommended:strong&&i===0})),
 total_products:p.length,recommended_product_id:strong?1:null,
 telegram_message:(strong?`لقيتلك أفضل ${p.length} منتجات من نون السعودية:\n\n`:`لقيتلك ${p.length} منتجات Beauty حقيقية من نون السعودية، لكن بعض إشارات الجودة/التوفر غير مكتملة:\n\n`)+lines.join('\n\n')+'\n\nاختار رقم المنتج اللي عايز نشتغل عليه.',
 search_success:true,source:'Noon Saudi',target_country:'Saudi Arabia',quality_mode:input.quality_mode
}}];
